  font: inherit;
  font-size: clamp(0.9375rem, 1.5vw, 1rem);
  font-weight: 600;
  cursor: pointer;
}

.confirm-btn:hover {
  background: var(--myelin-wash);
}

.confirm-btn.is-primary {
  border-color: var(--myelin);
  background: var(--myelin);
  color: var(--slide);
}

.confirm-btn.is-primary:hover {
  filter: brightness(1.08);
}

@keyframes confirm-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .confirm-dialog {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .confirm-dialog {
    animation: none;
  }
}
